{
 "kind": "sequence",
 "format": 1,
 "id": "seq_deadball_booth_cut",
 "name": "Deadball: a cut to the booth",
 "set": "set_hughson_booth",
 "roles": {
  "pbp": {
   "mark": "pbp",
   "label": "Play-by-play"
  },
  "col": {
   "mark": "col",
   "label": "Colour"
  }
 },
 "wall": "feed",
 "wallText": "{venue}",
 "wallSub": "{show}",
 "beats": [
  {
   "id": "b1",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "Grand slam, {cutMan.name}. Four runs on one swing.",
     "{cutMan.name} has cleared the bases with one swing. Grand slam."
    ]
   },
   "gfx": [
    {
     "kind": "score",
     "title": "{status}",
     "left": "{away}",
     "leftScore": "{awayScore}",
     "right": "{home}",
     "rightScore": "{homeScore}",
     "sub": "{venue}",
     "at": 0.2,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "cut",
     "op": "=",
     "value": "grandslam"
    }
   ]
  },
  {
   "id": "b2",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "{cutMan.name} has tied it with {cutPlay}. {away} {awayScore}, {home} {homeScore}.",
     "And we're level. {cutMan.name} with {cutPlay}, and it's {awayScore} apiece."
    ]
   },
   "gfx": [
    {
     "kind": "score",
     "title": "{status}",
     "left": "{away}",
     "leftScore": "{awayScore}",
     "right": "{home}",
     "rightScore": "{homeScore}",
     "sub": "{venue}",
     "at": 0.2,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "cut",
     "op": "=",
     "value": "late"
    },
    {
     "fact": "cutTied",
     "op": "=",
     "value": "true"
    }
   ]
  },
  {
   "id": "b3",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "{cutMan.name} puts {cutMan.team} in front with {cutPlay}. {away} {awayScore}, {home} {homeScore}.",
     "There's the lead. {cutMan.name}, {cutPlay}, and {cutMan.team} are ahead."
    ]
   },
   "gfx": [
    {
     "kind": "score",
     "title": "{status}",
     "left": "{away}",
     "leftScore": "{awayScore}",
     "right": "{home}",
     "rightScore": "{homeScore}",
     "sub": "{venue}",
     "at": 0.2,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "cut",
     "op": "=",
     "value": "late"
    },
    {
     "fact": "cutTied",
     "op": "=",
     "value": "false"
    }
   ]
  },
  {
   "id": "b4",
   "shot": {
    "cam": "cam3",
    "frame": "close",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "He was waiting on that pitch the whole at-bat. You don't leave one there.",
     "That's the pitch you'd like back. It was up and it was over the plate."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "cut",
     "op": "=",
     "value": "grandslam"
    }
   ]
  },
  {
   "id": "b5",
   "shot": {
    "cam": "cam3",
    "frame": "close",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "Now it's a ballgame. Whoever's got the deeper bullpen wins this one.",
     "Late in a game, that's the swing you want. It changes how both managers play it."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "cut",
     "op": "=",
     "value": "late"
    }
   ]
  },
  {
   "id": "b6",
   "shot": {
    "cam": "cam2",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "Back down to the field.",
     "Let's get back to it."
    ]
   },
   "gfx": []
  }
 ]
}
